 "content": "def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(anchors) < 2:
        return out

    def neighborhood_count(pos):
        r, c = pos
        return sum(
            1
            for rr, row in enumerate(grid)
            for cc, v in enumerate(row)
            if v and v != 5 and (rr != r or cc != c)
        )

    # The 5 embedded in the colored pattern is its origin; the other 5 marks
    # where to reproduce that pattern.
    source = max(anchors, key=neighborhood_count)
    target = min((p for p in anchors if p != source), key=neighborhood_count)
    sr, sc = source
    tr, tc = target
    out[tr][tc] = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and value != 5:
                rr, cc = tr + r - sr, tc + c - sc
                if 0 <= rr < len(grid) and 0 <= cc < len(row):
                    out[rr][cc] = value
    return out
